"""The season the planner reads: typed, immutable, and only the columns the planner uses."""

from __future__ import annotations

from dataclasses import dataclass

WEEKS_PER_MONTH = 4


@dataclass(frozen=True)
class Circuit:
    cid: str
    region: str
    miles: int
    cost: int           # $k to trim the circuit
    risk: int           # $k a year of tree-caused outage risk that a trim removes
    weeks: int          # crew-weeks of work to trim it


@dataclass(frozen=True)
class Season:
    name: str
    budget: int         # $k for the year's trimming
    crews: int          # crews working the season
    months: int         # months in the season, each WEEKS_PER_MONTH weeks
    circuits: tuple[Circuit, ...]

    def circuit(self, cid: str) -> Circuit:
        return next(c for c in self.circuits if c.cid == cid)


def season_from_dict(raw: dict) -> Season:
    """Read the columns the planner uses. Columns it does not use yet are ignored."""
    circuits = tuple(Circuit(c["id"], c["region"], int(c["miles"]), int(c["cost"]), int(c["risk"]),
                             int(c["weeks"]))
                     for c in raw["circuits"])
    return Season(raw.get("name", "season"), int(raw["budget"]), int(raw["crews"]), int(raw["months"]),
                  circuits)

"""A seeded generator of fictional trimming seasons, in the shape the circuit inventory exports.

Each column is drawn from its own random stream, named after the seed, the size and the column, so
adding a column later never changes the values of the columns already there.
"""

from __future__ import annotations

import math
import random

SIZES = {"tiny": 6, "small": 20, "medium": 60}
CREWS = {"tiny": 1, "small": 2, "medium": 6}
MONTHS = 6                                                     # April to September
REGIONS = ("North", "River", "Hills")


def stream(seed: int, size: str, column: str) -> random.Random:
    return random.Random(f"{seed}-{size}-{column}")


def scenario(size: str = "small", seed: int = 54) -> dict:
    """One season: a budget and the circuits, as plain JSON-ready values."""
    n = SIZES[size]
    draw = stream(seed, size, "circuits")
    circuits = []
    for i in range(1, n + 1):
        miles = draw.randint(8, 40)
        circuits.append({
            "id": f"C{i:02d}",
            "region": draw.choice(REGIONS),
            "miles": miles,
            "cost": round(miles * draw.uniform(3.0, 6.0)),       # $k to trim the whole circuit
            "risk": round(miles * draw.uniform(2.0, 12.0)),      # $k a year of tree-caused outage risk
        })
    work = stream(seed, size, "weeks")
    for c in circuits:
        c["weeks"] = math.ceil(c["miles"] / work.uniform(4.0, 7.0))     # crew-weeks to trim it
    budget = round(0.45 * sum(c["cost"] for c in circuits))
    return {"name": f"{size}-{seed}", "budget": budget, "crews": CREWS[size], "months": MONTHS,
            "circuits": circuits}

"""Turn a season into a plan: a 0-1 knapsack over the circuits, solved by HiGHS through MathOpt."""

from __future__ import annotations

from dataclasses import dataclass, field

from ortools.math_opt.python import mathopt

from vegcrew.data import Season

EXACT = mathopt.SolveParameters(relative_gap_tolerance=0.0)
STATUS = {mathopt.TerminationReason.OPTIMAL: "OPTIMAL", mathopt.TerminationReason.FEASIBLE: "FEASIBLE",
          mathopt.TerminationReason.INFEASIBLE: "INFEASIBLE"}


@dataclass(frozen=True)
class Trim:
    cid: str
    month: int = 0                                  # stub for lesson 14.1.2


@dataclass(frozen=True)
class Plan:
    status: str                                     # OPTIMAL, FEASIBLE, INFEASIBLE or NOT_SOLVED
    trims: dict[str, Trim] = field(default_factory=dict)
    cost: int = 0                                   # $k spent
    risk_removed: int = 0                           # $k a year of risk the trims remove


def build(season: Season) -> tuple[mathopt.Model, dict[str, mathopt.Variable]]:
    model = mathopt.Model(name=f"trim_{season.name}")
    x = {c.cid: model.add_binary_variable(name=f"x_{c.cid}") for c in season.circuits}
    model.add_linear_constraint(sum(c.cost * x[c.cid] for c in season.circuits) <= season.budget,
                                name="budget")
    model.maximize(sum(c.risk * x[c.cid] for c in season.circuits))
    return model, x


def make_plan(season: Season) -> Plan:
    """Choose the circuits to trim this year: the most risk removed within the budget."""
    model, x = build(season)
    result = mathopt.solve(model, mathopt.SolverType.HIGHS, params=EXACT)
    status = STATUS.get(result.termination.reason, result.termination.reason.name)
    if status not in ("OPTIMAL", "FEASIBLE"):
        return Plan(status)
    chosen = [c for c in season.circuits if result.variable_values(x[c.cid]) > 0.5]
    return Plan(status, {c.cid: Trim(c.cid) for c in chosen},
                cost=sum(c.cost for c in chosen), risk_removed=sum(c.risk for c in chosen))


def solve_quietly(model: mathopt.Model) -> mathopt.SolveResult:
    """Solves the model with HiGHS at a relative gap of zero and returns the SolveResult, with nothing HiGHS writes at the C level reaching the program's standard output."""
    return None

